class Program
{
    static void Main(string[] args)
    {
        int limit = 100;
        List<long> fibonacciNumbers = GenerateFibonacciNumbers(limit);

        foreach (long number in fibonacciNumbers)
        {
            Console.WriteLine(number);
        }
