    static List<long> GenerateFibonacciNumbers(int limit)
    {
        List<long> fibonacciNumbers = new List<long>();
        fibonacciNumbers.Add(0); // First Fibonacci number
        fibonacciNumbers.Add(1); // Second Fibonacci number

        for (int i = 2; i < limit; i++)
        {
            long newNumber = fibonacciNumbers[i - 1] + fibonacciNumbers[i - 2];

            if (IsPrime(newNumber) && newNumber % 5 == 0 && HasUniqueDigits(newNumber))
            {
                fibonacciNumbers.Add(newNumber);
            }
        }

        return fibonacciNumbers;
    }

    static bool IsPrime(long number)
    {
        if (number < 2)
            return false;

        for (int i = 2; i <= Math.Sqrt(number); i++)
        {
            if (number % i == 0)
                return false;
        }

        return true;
    }

    static bool HasUniqueDigits(long number)
    {
        HashSet<int> digits = new HashSet<int>();

        while (number > 0)
        {
            int digit = (int)(number % 10);
            if (digits.Contains(digit))
                return false;

            digits.Add(digit);
            number /= 10;
        }

        return true;
    }
}
